<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Support\Str;
class Backup extends Model{protected $fillable=['tenant_id','application_deployment_id','server_id','backup_destination_id','backup_schedule_id','created_by','uuid','name','backup_type','status','storage_path','size_bytes','checksum','metadata','started_at','completed_at','expires_at','restored_at','last_error'];protected static function booted():void{static::creating(fn($m)=>$m->uuid??=(string)Str::uuid());}protected function casts():array{return['metadata'=>'array','started_at'=>'datetime','completed_at'=>'datetime','expires_at'=>'datetime','restored_at'=>'datetime'];}public function getRouteKeyName():string{return'uuid';}public function deployment():BelongsTo{return $this->belongsTo(ApplicationDeployment::class,'application_deployment_id')->withTrashed();}public function server():BelongsTo{return $this->belongsTo(Server::class)->withTrashed();}public function destination():BelongsTo{return $this->belongsTo(BackupDestination::class,'backup_destination_id');}public function schedule():BelongsTo{return $this->belongsTo(BackupSchedule::class,'backup_schedule_id');}public function sizeLabel():string{return $this->size_bytes>=1073741824?number_format($this->size_bytes/1073741824,1).' GB':number_format($this->size_bytes/1048576,1).' MB';}public function statusTone():string{return match($this->status){'successful'=>'success','failed'=>'failed','running'=>'running',default=>'warning'};}public function typeLabel():string{return ucfirst($this->backup_type);}public function destinationLabel():string{return $this->destination?->name??'Local encrypted storage';}public function resolvedApplication():?Application{return $this->deployment?->application;}public function applicationName():string{return $this->resolvedApplication()?->name??$this->deployment?->name??'—';}public function canDownload():bool{return $this->status==='successful'&&filled($this->storage_path);}public function canRestore():bool{return $this->status==='successful';}}
